blocks.mysql:
-- MySQL prefers CAST; the comparison follows the same rules
SELECT * FROM products
WHERE  created_on = CAST('2024-01-15' AS DATE);

blocks.code:
-- This matches nothing: NULL = NULL is UNKNOWN, not TRUE
SELECT * FROM users WHERE email = NULL;

-- These are the correct filters
SELECT * FROM users WHERE email IS NULL;
SELECT * FROM users WHERE email IS NOT NULL;

blocks.pg:
-- RETURNING can also return just-modified rows:
UPDATE products SET price = 22.50 WHERE id = 4 RETURNING id, price;
INSERT ... ON CONFLICT (slug) DO UPDATE SET price = EXCLUDED.price
  RETURNING id;

blocks.mysql:
-- MySQL 8.0 has no RETURNING; read the key afterwards:
INSERT INTO products (name, price) VALUES ('T-Shirt', 19.99);
SELECT LAST_INSERT_ID();

